import time

from functools import wraps


def retry(times, delay):
    def decorator(method):
        @wraps(method)
        def wrapper(*args, **kwargs):
            attempt = 0
            exc_list = []
            while attempt < times:
                try:
                    return method(*args, **kwargs)
                except Exception as e:
                    attempt += 1
                    time.sleep(delay)
                    exc_list.append(e)
            raise Exception(f"{method} failed after {retry} times due to {exc_list}")

        return wrapper
    return decorator

